DO $$
DECLARE
    tbl text;
    tables_to_add text[] := ARRAY[
        'products', 'sales', 'sale_items', 'debtors', 'debtor_payments', 'debtor_charges',
        'categories', 'tenants', 'users', 'activity_log', 'expense_categories', 'expenses'
    ];
BEGIN
    BEGIN
        ALTER TABLE users ADD COLUMN access_modules TEXT[] DEFAULT NULL;
    EXCEPTION
        WHEN duplicate_column THEN NULL;
    END;

    FOREACH tbl IN ARRAY tables_to_add LOOP
        IF NOT EXISTS (
            SELECT 1 
            FROM pg_publication_tables 
            WHERE pubname = 'supabase_realtime' 
            AND tablename = tbl
        ) THEN
            EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE %I', tbl);
        END IF;
    END LOOP;
END
$$;
